head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.t1_onclick = function(e) {
    widgetContainer1.resizeWidget("widget0", 2, 2);
};
scwin.trigger2_onclick = function(e) {
    widgetContainer1.resizeWidget("widget0", 2, 2, {
        "force": true
    });
};
scwin.__parseStyle = function(style, type, append) {
    var value = parseFloat(style);
    return value * append + type;
}
scwin.checkVal1 = function() {
    return scwin.__getDom($p.id + 'widgetContainer1_widget0').style.width == widthInit;
}
scwin.checkVal2 = function() {
    return scwin.__getDom($p.id + 'widgetContainer1_widget0').style.height == heightInit;
}
scwin.checkVal3 = function() {
    return scwin.__getDom($p.id + 'widgetContainer1_widget0').style.width >= scwin.__parseStyle(widthInit, '%', 2);
}
scwin.checkVal4 = function() {
    return scwin.__getDom($p.id + 'widgetContainer1_widget0').style.height >= scwin.__parseStyle(heightInit, '%', 2);
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    widgetContainer1.addWidgets({
        title: "widget0",
        src: null,
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 06-Feb-2018
    window.widthInit = scwin.__getDom($p.id + "widgetContainer1_widget0").style.width;
    window.heightInit = scwin.__getDom($p.id + "widgetContainer1_widget0").style.height;
    //end
}
